struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i);
  let b = hash21(i + vec2f(1.0, 0.0));
  let c = hash21(i + vec2f(0.0, 1.0));
  let d = hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn fbm(p: vec2f) -> f32 {
  var q = p;
  var v = 0.0;
  v += 0.50000 * noise(q); q = q * 2.04 + vec2f(1.7, 9.2);
  v += 0.25000 * noise(q); q = q * 2.03 + vec2f(8.3, 2.8);
  v += 0.12500 * noise(q); q = q * 2.01 + vec2f(3.1, 5.4);
  v += 0.06250 * noise(q); q = q * 2.05 + vec2f(7.9, 1.6);
  v += 0.03125 * noise(q);
  return v;
}

fn rot(p: vec2f, a: f32) -> vec2f {
  let c = cos(a);
  let s = sin(a);
  return vec2f(c * p.x - s * p.y, s * p.x + c * p.y);
}

fn vortex(p: vec2f, c: vec2f, k: f32) -> vec2f {
  let d = p - c;
  let r = length(d) + 0.020;
  return rot(d, k / r) + c;
}

fn interference(d: f32) -> vec3f {
  let tau = max(d, 0.0);
  let r = 0.5 - 0.5 * cos(6.283185 * tau / 0.655);
  let g = 0.5 - 0.5 * cos(6.283185 * tau / 0.538);
  let b = 0.5 - 0.5 * cos(6.283185 * tau / 0.428);
  return vec3f(r, g, b);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  var p = (uv - vec2f(0.49, 0.51)) * vec2f(0.5625, 1.0);

  p = vortex(p, vec2f(-0.03, 0.08), 0.24 + 0.03 * sin(t * 0.31));
  p = vortex(p, vec2f(0.17, -0.23), -0.14);
  p = vortex(p, vec2f(-0.19, -0.35), 0.09);

  let drift = t * 0.047;
  var q = p * 2.25 + vec2f(drift * 0.55, -drift * 0.28);

  let w1 = vec2f(
    fbm(q * 1.12 + vec2f(0.20, t * 0.06)),
    fbm(q * 1.12 + vec2f(5.70, -t * 0.05))
  );
  q += (w1 - vec2f(0.5)) * 0.98;

  let w2 = vec2f(
    fbm(q * 2.48 + vec2f(t * 0.04, 1.80)),
    fbm(q * 2.48 + vec2f(8.20, t * 0.033))
  );
  q += (w2 - vec2f(0.5)) * 0.50;

  let w3 = vec2f(
    fbm(q * 5.20 + vec2f(2.4, 0.7)),
    fbm(q * 5.20 + vec2f(0.9, 4.1))
  );
  q += (w3 - vec2f(0.5)) * 0.17;

  var thick = fbm(q * 3.45 + vec2f(0.15, -0.22));
  thick = mix(thick, fbm(q * 6.9 + w2 * 1.45), 0.30);
  thick = pow(clamp(thick, 0.0, 1.0), 1.48);

  let contour = sin(thick * 24.0 + fbm(q * 8.2) * 2.6);
  let filament = abs(contour);
  let optical = 0.05 + thick * 2.95 + contour * 0.07;

  var col = interference(optical);
  col = pow(col, vec3f(0.86, 1.08, 0.88));

  let lime = clamp(col.g - max(col.r, col.b) * 0.90, 0.0, 1.0);
  col = mix(col, vec3f(0.07, 0.60, 0.63), lime);

  let goldw = clamp(min(col.r, col.g * 1.20) - col.b * 1.05, 0.0, 1.0);
  col = mix(col, vec3f(0.95, 0.70, 0.16), goldw * 0.70);

  let magw = clamp(min(col.r, col.b) - col.g * 0.80, 0.0, 1.0);
  col = mix(col, vec3f(0.90, 0.07, 0.52), magw * 0.42);

  let tealw = clamp(min(col.g, col.b) - col.r * 0.75, 0.0, 1.0);
  col = mix(col, vec3f(0.05, 0.68, 0.64), tealw * 0.58);

  let firstGold = smoothstep(0.26, 0.33, thick) * (1.0 - smoothstep(0.40, 0.48, thick));
  let petrol = smoothstep(0.48, 0.56, thick) * (1.0 - smoothstep(0.66, 0.78, thick));
  let magBand = smoothstep(0.36, 0.44, thick) * (1.0 - smoothstep(0.52, 0.60, thick));
  col = mix(col, vec3f(0.93, 0.68, 0.14), firstGold * 0.55);
  col = mix(col, vec3f(0.04, 0.67, 0.63), petrol * 0.50);
  col = mix(col, vec3f(0.88, 0.08, 0.50), magBand * 0.40);

  col.g *= mix(0.58, 1.0, clamp(col.r * 0.65 + col.b * 0.85, 0.0, 1.0));
  col *= vec3f(1.10, 0.92, 1.04);

  let well = smoothstep(0.14, 0.40, thick);
  let water = vec3f(0.007, 0.008, 0.012);
  let toxic = vec3f(0.06, 0.012, 0.040);
  col = mix(mix(water, toxic, 0.24 * thick), col, well);

  let ridge = pow(1.0 - filament, 11.0) * well;
  col += vec3f(0.92, 0.64, 0.16) * ridge * 0.26;
  col += vec3f(0.72, 0.08, 0.42) * pow(thick, 4.5) * 0.09;

  let sheen = pow(clamp(1.0 - abs(uv.y - 0.40 - 0.05 * sin(uv.x * 5.5 + t)) * 2.0, 0.0, 1.0), 16.0);
  col += vec3f(0.52, 0.36, 0.22) * sheen * 0.055 * well;

  let vig = smoothstep(0.96, 0.16, length(p * vec2f(1.16, 0.90)));
  col *= 0.55 + 0.45 * vig;
  col = pow(clamp(col, vec3f(0.0), vec3f(1.18)), vec3f(0.93));

  return vec4f(col, 1.0);
}
